class Solution { public int numPrimeArrangements(int n){boolean[] prime=new boolean[n+1];Arrays.fill(prime,true);if(n>=0)prime[0]=false;if(n>=1)prime[1]=false;for(int value=2;value*value<=n;value++)if(prime[value])for(int multiple=value*value;multiple<=n;multiple+=value)prime[multiple]=false;int count=0;for(boolean value:prime)if(value)count++;long answer=1,mod=1000000007L;for(int value=2;value<=count;value++)answer=answer*value%mod;for(int value=2;value<=n-count;value++)answer=answer*value%mod;return (int)answer;} }
